package com.siansiansu.taigikeyboard.ime.clipboard

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Represents a clipboard item containing plain text.
 *
 * @property id Primary key (auto-generated)
 * @property text The plain text content
 * @property timestampMs Creation timestamp in milliseconds
 * @property isPinned Whether the item is pinned (for future feature)
 */
@Entity(tableName = "clipboard_history")
data class ClipboardItem(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0,
    val text: String,
    val timestampMs: Long = System.currentTimeMillis(),
    val isPinned: Boolean = false
) {
    companion object {
        /**
         * Creates a new ClipboardItem with the given text.
         */
        fun fromText(text: String): ClipboardItem {
            return ClipboardItem(
                id = 0, // Auto-generated by Room
                text = text,
                timestampMs = System.currentTimeMillis(),
                isPinned = false
            )
        }
    }

    /**
     * Returns a preview of the text (first line, max 100 chars).
     */
    fun getPreview(): String {
        val firstLine = text.lines().firstOrNull() ?: ""
        return if (firstLine.length > 100) {
            firstLine.substring(0, 100) + "..."
        } else {
            firstLine
        }
    }
}
